'use client';
import {useEffect,useState} from 'react';
import Link from 'next/link';
import Image from 'next/image';
import {ArrowLeft,MapPin,Building2,Sparkles,Clock3,Send,FileText,Loader2,CheckCircle2} from 'lucide-react';
import {request,jsonBody} from '@/lib/client';
import {CATEGORIES,STATUSES} from '@/lib/constants';
import {Status,ErrorBox,Loading} from './city-ui';
import {SafeDate} from './safe-format';
export default function TicketDetail({id,admin}:{id:string;admin:boolean}){const [ticket,setTicket]=useState<any>(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [loading,setLoading]=useState(true);const [success,setSuccess]=useState('');const [broken,setBroken]=useState<string[]>([]);const [reload,setReload]=useState(0);const [conflict,setConflict]=useState(false);const [draft,setDraft]=useState<string|null>(null);
 useEffect(()=>{let live=true;request(`/api/tickets/${id}`).then((data:any)=>{if(live)setTicket(data);}).catch((e:Error)=>{console.error(e);if(live)setError(e.message);}).finally(()=>{if(live)setLoading(false);});return()=>{live=false;};},[id,reload]);
 async function update(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(busy||conflict)return;setBusy(true);setError('');setSuccess('');const f=new FormData(e.currentTarget);try{const response=await fetch(`/api/tickets/${id}`,{method:'PATCH',...jsonBody({status:f.get('status'),adminResponse:f.get('adminResponse'),expectedUpdatedAt:ticket.updatedAt})});const body=await response.json();if(response.status===409)setConflict(true);if(!response.ok)throw new Error(body.error??'Güncellenemedi.');setDraft(null);setSuccess('Başvuru güncellendi.');setReload((v)=>v+1);}catch(e){console.error(e);setError(e instanceof Error?e.message:'Güncellenemedi.');}finally{setBusy(false);}}
 async function refreshConflict(){if(busy)return;setBusy(true);try{const fresh=await request(`/api/tickets/${id}`);setTicket(fresh);setConflict(false);setError('');setSuccess('Güncel durum yüklendi. Yanıt taslağınızı kontrol ederek tekrar gönderebilirsiniz.');}catch(e){console.error(e);setError(e instanceof Error?e.message:'Güncel durum yüklenemedi.');}finally{setBusy(false);}}
 const transitions:Record<string,string[]>={OPEN:['OPEN','IN_PROGRESS','REJECTED'],IN_PROGRESS:['IN_PROGRESS','RESOLVED','REJECTED'],RESOLVED:['RESOLVED'],REJECTED:['REJECTED']};
 return <div><Link href="/basvurular" className="btn-light mb-5"><ArrowLeft size={15}/>Başvurulara dön</Link><h1 className="page-title">Başvuru detayları</h1><p className="mt-2 text-sm text-muted-foreground">Başvurunun içeriği, yönlendirildiği birim ve süreç geçmişi.</p><ErrorBox message={error}/>{loading?<Loading/>:ticket&&<div className="mt-7 grid gap-6 lg:grid-cols-[1fr_300px]"><div className="space-y-5"><section className="panel p-6"><div className="mb-4 flex items-center justify-between"><span className="font-mono text-xs text-muted-foreground">#{ticket?.id?.slice(0,8).toUpperCase()}</span><Status value={ticket?.status}/></div><h2 className="text-xl font-semibold">{ticket?.title}</h2><div className="my-4 flex flex-wrap gap-4 text-xs text-muted-foreground"><span className="flex items-center gap-1"><MapPin size={14}/>{ticket?.district}{ticket?.neighborhood?` / ${ticket.neighborhood}`:''}</span><span className="flex items-center gap-1"><Clock3 size={14}/><SafeDate date={ticket?.createdAt} locale="tr-TR" options={{dateStyle:'long'}}/></span></div><p className="whitespace-pre-wrap text-sm leading-relaxed">{ticket?.description}</p>{!!ticket?.photos?.length&&<div className="mt-6 grid grid-cols-2 gap-3">{ticket.photos.map((photo:any)=><a key={photo.id} href={photo.url} target="_blank" rel="noreferrer" className="relative aspect-video overflow-hidden rounded-lg bg-muted" aria-label={`${photo.name} fotoğrafını büyüt`}>{broken.includes(photo.id)?<span className="grid h-full place-items-center text-xs text-muted-foreground">Fotoğraf yüklenemedi. Sayfayı yenileyin.</span>:<Image src={photo.url} alt={photo.name} fill unoptimized sizes="400px" className="object-contain" onError={()=>setBroken((p)=>[...p,photo.id])}/>}</a>)}</div>}</section><section className="panel p-6"><h2 className="section-title mb-5 flex items-center gap-2"><Clock3 size={18} className="text-primary"/>Süreç geçmişi</h2>{ticket?.events?.map((event:any)=><div key={event.id} className="relative ml-2 border-l border-border pb-6 pl-6 last:pb-1"><span className="absolute -left-2 top-0 grid h-4 w-4 place-items-center rounded-full bg-accent"><span className="h-1.5 w-1.5 rounded-full bg-primary"/></span><div className="flex flex-wrap items-center gap-2"><span className="text-xs font-semibold">{STATUSES[event.status]}</span><SafeDate date={event.createdAt} locale="tr-TR" options={{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Istanbul'}} className="text-[10px] text-muted-foreground"/></div><p className="mt-2 whitespace-pre-wrap text-sm leading-relaxed text-muted-foreground">{event.message}</p></div>)}</section>{admin&&<form key={ticket?.updatedAt} onSubmit={update} className="panel space-y-4 p-6"><h2 className="section-title flex items-center gap-2"><Send size={18} className="text-primary"/>Başvuruyu yanıtla</h2><label className="field">Durum<select name="status" defaultValue={ticket?.status}>{transitions[ticket?.status]?.map((k)=><option key={k} value={k}>{STATUSES[k]}</option>)}</select></label><label className="field">Vatandaşa yanıt<textarea name="adminResponse" rows={4} required minLength={5} maxLength={3000} value={draft??ticket?.adminResponse??''} onChange={(e)=>setDraft(e.target.value)} placeholder="Yapılan işlemi ve sürecin sonraki adımını açıklayın."/></label>{success&&<p role="status" className="text-sm text-chart-4">{success}</p>}{conflict&&<button type="button" onClick={refreshConflict} disabled={busy} className="btn-light">Taslağı koruyarak güncel durumu yükle</button>}<button disabled={busy||conflict} className="btn">{busy?<Loader2 className="animate-spin" size={15}/>:<CheckCircle2 size={15}/>}Güncelle ve yanıtla</button></form>}</div><aside className="space-y-5"><section className="panel p-5"><Building2 size={22} className="mb-4 text-primary"/><h3 className="text-xs font-semibold text-muted-foreground">Yönlendirilen birim</h3><p className="mt-2 text-base font-semibold">{ticket?.assignedDepartment}</p><div className="mt-5 border-t pt-4"><h3 className="text-xs text-muted-foreground">Hizmet kategorisi</h3><p className="mt-2 text-sm font-medium">{CATEGORIES[ticket?.category]}</p><p className="mt-3 text-[10px] text-muted-foreground">Seçilen: {CATEGORIES[ticket?.selectedCategory]}</p></div></section><section className="rounded-xl bg-accent p-5"><Sparkles size={22} className="mb-3 text-primary"/><h3 className="text-sm font-semibold">Yapay zekâ değerlendirmesi</h3><p className="mt-4 text-3xl font-semibold text-primary">%{Math.round((ticket?.aiConfidenceScore??0)*100)}</p><p className="mt-2 text-xs text-muted-foreground">Kategori ve birim için model güven tahmini.</p><p className="mt-4 text-[10px] leading-relaxed text-muted-foreground">Bu değer doğrulanmış bir olasılık değildir. Nihai değerlendirme yetkili birim tarafından yapılır.</p></section><p className="px-2 text-[10px] leading-relaxed text-muted-foreground">Yönlendirme bu uygulama içinde yapılır; gerçek belediye sistemlerine otomatik aktarım yoktur.</p></aside></div>}</div>;
}
